code.java:
class Solution {
    public int[] sectionCounts(int n, int[][] groups) {
        int[] out = new int[n];
        for (int[] g : groups) {
            for (int i = g[0]; i <= g[1]; i++) out[i] += g[2];
        }
        return out;
    }
}

