class Solution {
    public int[] sectionCounts(int n, int[][] groups) {
        int[] diff = new int[n + 1];
        for (int[] g : groups) {
            diff[g[0]] += g[2];
            diff[g[1] + 1] -= g[2];
        }
        int[] out = new int[n];
        int running = 0;
        for (int i = 0; i < n; i++) {
            running += diff[i];
            out[i] = running;
        }
        return out;
    }
}

